import requests
import time


def upload(path, url):
    max_retries = 3
    base_delay = 1

    with open(path, 'rb') as fh:
        data = fh.read()

    for attempt in range(max_retries):
        try:
            response = requests.post(url, data=data)
            return response
        except Exception as e:
            if attempt < max_retries - 1:
                delay = base_delay * (2 ** attempt)
                time.sleep(delay)
            else:
                raise

