import requests


def upload(path, url):
    max_attempts = 3
    backoff_delays = [0.5, 1.0, 2.0]

    for attempt in range(max_attempts):
        try:
            with open(path, 'rb') as fh:
                response = requests.post(url, data=fh.read())
                return response
        except Exception as e:
            if attempt < max_attempts - 1:
                delay = backoff_delays[attempt]
                print(f"Upload failed (attempt {attempt + 1}/{max_attempts}), retrying in {delay}s...")
                time.sleep(delay)
            else:
                raise

